#include <bits/stdc++.h>
using namespace std;

int main() {
    ostringstream all;
    all << cin.rdbuf();
    string text = all.str();
    if (!text.empty() && text.back() == '\n') text.pop_back();
    vector<string> lines;
    size_t start = 0;
    while (true) {
        size_t end = text.find('\n', start);
        if (end == string::npos) {
            lines.push_back(text.substr(start));
            break;
        }
        lines.push_back(text.substr(start, end - start));
        start = end + 1;
    }
    int n = stoi(lines[0]);
    unordered_map<string, pair<string, string>> records;  // start -> (end, payload)
    unordered_set<string> ends;
    records.reserve(2 * n);
    ends.reserve(2 * n);
    for (int i = 0; i < n; i++) {
        const string &keys = lines[1 + 2 * i];
        size_t a = keys.find_first_not_of(' '), b = keys.find(' ', a);
        size_t c = keys.find_first_not_of(' ', b), e = keys.find_first_of(" \r", c);
        string from = keys.substr(a, b - a), to = keys.substr(c, e == string::npos ? string::npos : e - c);
        string payload = 2 + 2 * i < (int)lines.size() ? lines[2 + 2 * i] : "";
        records[from] = {to, payload};
        ends.insert(to);
    }
    // the chain starts at the only key that is no record's end
    string current;
    for (auto &[key, value] : records)
        if (!ends.count(key)) {
            current = key;
            break;
        }
    string result;
    for (int i = 0; i < n; i++) {
        auto &record = records[current];
        result += record.second;
        current = record.first;
    }
    cout << result << "\n";
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String text = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
        if (text.endsWith("\n")) text = text.substring(0, text.length() - 1);
        String[] lines = text.split("\n", -1);
        int n = Integer.parseInt(lines[0].trim());
        Map<String, String[]> records = new HashMap<>(); // start -> {end, payload}
        Set<String> ends = new HashSet<>();
        for (int i = 0; i < n; i++) {
            String line = lines[1 + 2 * i].trim();
            int space = line.indexOf(' ');
            String[] keys = {line.substring(0, space), line.substring(space + 1).trim()};
            String payload = 2 + 2 * i < lines.length ? lines[2 + 2 * i] : "";
            records.put(keys[0], new String[] {keys[1], payload});
            ends.add(keys[1]);
        }
        // the chain starts at the only key that is no record's end
        String current = null;
        for (String key : records.keySet())
            if (!ends.contains(key)) {
                current = key;
                break;
            }
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String[] record = records.get(current);
            result.append(record[1]);
            current = record[0];
        }
        result.append('\n');
        PrintStream out = new PrintStream(new FileOutputStream(FileDescriptor.out), false, StandardCharsets.UTF_8);
        out.print(result);
        out.flush();
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"strings"
)

func main() {
	raw, _ := io.ReadAll(os.Stdin)
	text := strings.TrimSuffix(string(raw), "\n")
	lines := strings.Split(text, "\n")
	n, _ := strconv.Atoi(strings.TrimSpace(lines[0]))
	type record struct{ end, payload string }
	records := make(map[string]record, n) // keyed by start
	ends := make(map[string]bool, n)
	for i := 0; i < n; i++ {
		keys := strings.Fields(lines[1+2*i])
		payload := ""
		if 2+2*i < len(lines) {
			payload = lines[2+2*i]
		}
		records[keys[0]] = record{keys[1], payload}
		ends[keys[1]] = true
	}
	// the chain starts at the only key that is no record's end
	current := ""
	for key := range records {
		if !ends[key] {
			current = key
			break
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < n; i++ {
		r := records[current]
		w.WriteString(r.payload)
		current = r.end
	}
	w.WriteString("\n")
}
